<?php

namespace App\Auth;

use App\Model\Worker;

// Descobre quem está chamando a API a partir da chave enviada no header X-API-Key
final class ApiKeyAuth
{
    /**
     * @param array<string, ?string> $keys papel => chave (ex.: ['boss' => '...', 'worker' => '...'])
     * @param ?Worker $workers when given, keys generated by POST /worker are also accepted
     */
    public function __construct(private array $keys, private ?Worker $workers = null)
    {
    }

    // Devolve o papel dono da chave ('boss', 'worker'...) ou null se a chave não vale
    public function roleFor(?string $key): ?string
    {
        if ($key === null || $key === '') {
            return null;
        }

        foreach ($this->keys as $role => $expected) {
            // Chave não configurada no .env não pode liberar acesso (senão um header vazio passaria)
            if ($expected === null || $expected === '') {
                continue;
            }

            // hash_equals compara em tempo constante, para não vazar a chave pelo tempo de resposta
            if (hash_equals($expected, $key)) {
                return $role;
            }
        }

        // No .env key matched: try the per-worker keys. The database only stores the SHA-256,
        // so we hash what was sent and look for that hash. The key itself is never read back.
        // A timing difference here could only leak the hash, which is useless as a key.
        if ($this->workers !== null && $this->workers->findIdByApiKeyHash(hash('sha256', $key)) !== null) {
            return 'worker';
        }

        return null;
    }
}
